            reg_s3_0 <= s3_0;
            reg_s3_1 <= s3_1;
            reg_s3_2 <= s3_2;
            reg_s3_3 <= s3_3;
            reg_s3_4 <= s3_4;
            reg_s3_5 <= s3_5;
            reg_s3_6 <= s3_6;
            reg_s3_7 <= s3_7;
            reg_s3_8 <= s3_8;
            reg_s3_9 <= s3_9;
            reg_s3_10 <= s3_10;
            reg_s3_11 <= s3_11;
            reg_s3_12 <= s3_12;
            reg_s3_13 <= s3_13;
            reg_s3_14 <= s3_14;
            reg_s3_15 <= s3_15;
            reg_s3_16 <= s3_16;
            reg_s3_17 <= s3_17;
            reg_s3_18 <= s3_18;
            reg_s3_19 <= s3_19;
            reg_s3_20 <= s3_20;
            reg_s3_21 <= s3_21;
            reg_s3_22 <= s3_22;
            reg_s3_23 <= s3_23;
            reg_s3_24 <= s3_24;
            reg_s3_25 <= s3_25;
            reg_s3_26 <= s3_26;
            reg_s3_27 <= s3_27;
            reg_s3_28 <= s3_28;
            reg_s3_29 <= s3_29;
            reg_s3_30 <= s3_30;
            reg_s3_31 <= s3_31;
            valid_stage3 <= valid_stage2;
        end
    end

    // ---- Level 4: 32 -> 16 ----
    wire signed [43:0] s4_0 = reg_s3_0 + reg_s3_1;
    wire signed [43:0] s4_1 = reg_s3_2 + reg_s3_3;
    wire signed [43:0] s4_2 = reg_s3_4 + reg_s3_5;
    wire signed [43:0] s4_3 = reg_s3_6 + reg_s3_7;
    wire signed [43:0] s4_4 = reg_s3_8 + reg_s3_9;
    wire signed [43:0] s4_5 = reg_s3_10 + reg_s3_11;
    wire signed [43:0] s4_6 = reg_s3_12 + reg_s3_13;
    wire signed [43:0] s4_7 = reg_s3_14 + reg_s3_15;
    wire signed [43:0] s4_8 = reg_s3_16 + reg_s3_17;
    wire signed [43:0] s4_9 = reg_s3_18 + reg_s3_19;
    wire signed [43:0] s4_10 = reg_s3_20 + reg_s3_21;
    wire signed [43:0] s4_11 = reg_s3_22 + reg_s3_23;
    wire signed [43:0] s4_12 = reg_s3_24 + reg_s3_25;
    wire signed [43:0] s4_13 = reg_s3_26 + reg_s3_27;
    wire signed [43:0] s4_14 = reg_s3_28 + reg_s3_29;
    wire signed [43:0] s4_15 = reg_s3_30 + reg_s3_31;

    // ---- Pipeline register after level 4 ----
    reg signed [43:0] reg_s4_0, reg_s4_1, reg_s4_2, reg_s4_3, reg_s4_4, reg_s4_5, reg_s4_6, reg_s4_7, reg_s4_8, reg_s4_9, reg_s4_10, reg_s4_11, reg_s4_12, reg_s4_13, reg_s4_14, reg_s4_15;
    reg valid_stage4;

    always @(posedge clk_dsp or negedge rst_n_dsp) begin
        if (!rst_n_dsp) begin
            reg_s4_0 <= 44'sd0;
            reg_s4_1 <= 44'sd0;
            reg_s4_2 <= 44'sd0;
            reg_s4_3 <= 44'sd0;
            reg_s4_4 <= 44'sd0;
            reg_s4_5 <= 44'sd0;
            reg_s4_6 <= 44'sd0;
            reg_s4_7 <= 44'sd0;
            reg_s4_8 <= 44'sd0;
            reg_s4_9 <= 44'sd0;
            reg_s4_10 <= 44'sd0;
            reg_s4_11 <= 44'sd0;
            reg_s4_12 <= 44'sd0;
            reg_s4_13 <= 44'sd0;
            reg_s4_14 <= 44'sd0;
            reg_s4_15 <= 44'sd0;
            valid_stage4 <= 1'b0;
        end else begin
            reg_s4_0 <= s4_0;
            reg_s4_1 <= s4_1;
            reg_s4_2 <= s4_2;
            reg_s4_3 <= s4_3;
            reg_s4_4 <= s4_4;
            reg_s4_5 <= s4_5;
            reg_s4_6 <= s4_6;
            reg_s4_7 <= s4_7;
            reg_s4_8 <= s4_8;
            reg_s4_9 <= s4_9;
            reg_s4_10 <= s4_10;
            reg_s4_11 <= s4_11;
            reg_s4_12 <= s4_12;
            reg_s4_13 <= s4_13;
            reg_s4_14 <= s4_14;
            reg_s4_15 <= s4_15;
            valid_stage4 <= valid_stage3;
        end
    end

    // ---- Level 5: 16 -> 8 ----
    wire signed [44:0] s5_0 = reg_s4_0 + reg_s4_1;
    wire signed [44:0] s5_1 = reg_s4_2 + reg_s4_3;
    wire signed [44:0] s5_2 = reg_s4_4 + reg_s4_5;
    wire signed [44:0] s5_3 = reg_s4_6 + reg_s4_7;
    wire signed [44:0] s5_4 = reg_s4_8 + reg_s4_9;
    wire signed [44:0] s5_5 = reg_s4_10 + reg_s4_11;
    wire signed [44:0] s5_6 = reg_s4_12 + reg_s4_13;
    wire signed [44:0] s5_7 = reg_s4_14 + reg_s4_15;

    // ---- Pipeline register after level 5 ----
    reg signed [44:0] reg_s5_0, reg_s5_1, reg_s5_2, reg_s5_3, reg_s5_4, reg_s5_5, reg_s5_6, reg_s5_7;
    reg valid_stage5;

    always @(posedge clk_dsp or negedge rst_n_dsp) begin
        if (!rst_n_dsp) begin
            reg_s5_0 <= 45'sd0;
            reg_s5_1 <= 45'sd0;
            reg_s5_2 <= 45'sd0;
            reg_s5_3 <= 45'sd0;
            reg_s5_4 <= 45'sd0;
            reg_s5_5 <= 45'sd0;
            reg_s5_6 <= 45'sd0;
            reg_s5_7 <= 45'sd0;
            valid_stage5 <= 1'b0;
        end else begin
            reg_s5_0 <= s5_0;
            reg_s5_1 <= s5_1;
            reg_s5_2 <= s5_2;
            reg_s5_3 <= s5_3;
            reg_s5_4 <= s5_4;
            reg_s5_5 <= s5_5;
            reg_s5_6 <= s5_6;
            reg_s5_7 <= s5_7;
            valid_stage5 <= valid_stage4;
        end
    end

    // ---- Level 6: 8 -> 4 ----
    wire signed [45:0] s6_0 = reg_s5_0 + reg_s5_1;
    wire signed [45:0] s6_1 = reg_s5_2 + reg_s5_3;
    wire signed [45:0] s6_2 = reg_s5_4 + reg_s5_5;
    wire signed [45:0] s6_3 = reg_s5_6 + reg_s5_7;

    // ---- Pipeline register after level 6 ----
    reg signed [45:0] reg_s6_0, reg_s6_1, reg_s6_2, reg_s6_3;
    reg valid_stage6;

    always @(posedge clk_dsp or negedge rst_n_dsp) begin
        if (!rst_n_dsp) begin
            reg_s6_0 <= 46'sd0;
            reg_s6_1 <= 46'sd0;
            reg_s6_2 <= 46'sd0;
            reg_s6_3 <= 46'sd0;
            valid_stage6 <= 1'b0;
        end else begin
            reg_s6_0 <= s6_0;
            reg_s6_1 <= s6_1;
            reg_s6_2 <= s6_2;
            reg_s6_3 <= s6_3;
            valid_stage6 <= valid_stage5;
        end
    end

    // ---- Level 7: 4 -> 2 ----
    wire signed [46:0] s7_0 = reg_s6_0 + reg_s6_1;
    wire signed [46:0] s7_1 = reg_s6_2 + reg_s6_3;

    // ---- Pipeline register after level 7 ----
    reg signed [46:0] reg_s7_0, reg_s7_1;
    reg valid_stage7;

    always @(posedge clk_dsp or negedge rst_n_dsp) begin
        if (!rst_n_dsp) begin
            reg_s7_0 <= 47'sd0;
            reg_s7_1 <= 47'sd0;
            valid_stage7 <= 1'b0;
        end else begin
            reg_s7_0 <= s7_0;
            reg_s7_1 <= s7_1;
            valid_stage7 <= valid_stage6;
        end
    end

    // ---- Level 8: 2 -> 1 ----
    wire signed [47:0] s8_0 = reg_s7_0 + reg_s7_1;

    // ---- Pipeline register after level 8 ----
    reg signed [47:0] reg_s8_0;
    reg valid_stage8;

    always @(posedge clk_dsp or negedge rst_n_dsp) begin
        if (!rst_n_dsp) begin
            reg_s8_0 <= 48'sd0;
            valid_stage8 <= 1'b0;
        end else begin
            reg_s8_0 <= s8_0;
            valid_stage8 <= valid_stage7;
        end
    end

    // ---- Final output register ----
    always @(posedge clk_dsp or negedge rst_n_dsp) begin
        if (!rst_n_dsp) begin
            result_out   <= 24'sd0;
            result_valid <= 1'b0;
        end else begin
            result_out   <= reg_s8_0[39:16];
            result_valid <= valid_stage8;
        end
    end

    wire sample_valid_sync;
    sync_2ff #(.WIDTH(1)) u_sync_sample_valid (
        .clk      (clk_50),
        .rst_n    (rst_n),
        .async_in (sample_valid),
        .sync_out (sample_valid_sync)
    );

    (* keep = "true" *) reg [15:0] sample_counter;
    always @(posedge clk_50 or negedge rst_n) begin
        if (!rst_n)
            sample_counter <= 16'd0;
        else if (sample_valid_sync)
            sample_counter <= sample_counter + 16'd1;
    end

endmodule
